#!/bin/bash
# harden/harden_kernel.sh
# CIS Level 1: Kernel & Network Parameter Hardening via sysctl

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
source "$SCRIPT_DIR/utils/colors.sh"
source "$SCRIPT_DIR/utils/helpers.sh"

section "Hardening: Kernel & Network (sysctl)"

SYSCTL_CONF="/etc/sysctl.d/99-cis-hardening.conf"
backup_file "$SYSCTL_CONF"

cat > "$SYSCTL_CONF" << 'EOF'
# =============================================================================
# CIS Benchmark Level 1 - Kernel Hardening Parameters
# Ubuntu 22.04 LTS | Generated by cis-hardening tool
# =============================================================================

# ---- Network: IP Forwarding -------------------------------------------------
net.ipv4.ip_forward = 0
net.ipv6.conf.all.forwarding = 0

# ---- Network: Send Redirects ------------------------------------------------
net.ipv4.conf.all.send_redirects = 0
net.ipv4.conf.default.send_redirects = 0

# ---- Network: Source Routing ------------------------------------------------
net.ipv4.conf.all.accept_source_route = 0
net.ipv4.conf.default.accept_source_route = 0
net.ipv6.conf.all.accept_source_route = 0
net.ipv6.conf.default.accept_source_route = 0

# ---- Network: ICMP Redirects ------------------------------------------------
net.ipv4.conf.all.accept_redirects = 0
net.ipv4.conf.default.accept_redirects = 0
net.ipv6.conf.all.accept_redirects = 0
net.ipv6.conf.default.accept_redirects = 0
net.ipv4.conf.all.secure_redirects = 0
net.ipv4.conf.default.secure_redirects = 0

# ---- Network: Logging -------------------------------------------------------
net.ipv4.conf.all.log_martians = 1
net.ipv4.conf.default.log_martians = 1

# ---- Network: ICMP BoB's and broadcasts -------------------------------------
net.ipv4.icmp_echo_ignore_broadcasts = 1
net.ipv4.icmp_ignore_bogus_error_responses = 1

# ---- Network: TCP SYN cookies -----------------------------------------------
net.ipv4.tcp_syncookies = 1

# ---- Network: Reverse path filtering ----------------------------------------
net.ipv4.conf.all.rp_filter = 1
net.ipv4.conf.default.rp_filter = 1

# ---- IPv6: Disable if not required ------------------------------------------
net.ipv6.conf.all.disable_ipv6 = 1
net.ipv6.conf.default.disable_ipv6 = 1
net.ipv6.conf.lo.disable_ipv6 = 1

# ---- IPv6: Router advertisements -------------------------------------------
net.ipv6.conf.all.accept_ra = 0
net.ipv6.conf.default.accept_ra = 0

# ---- Kernel: Core dumps -----------------------------------------------------
fs.suid_dumpable = 0
kernel.core_uses_pid = 1

# ---- Kernel: ASLR (Address Space Layout Randomization) ---------------------
kernel.randomize_va_space = 2

# ---- Kernel: Restrict dmesg ------------------------------------------------
kernel.dmesg_restrict = 1

# ---- Kernel: Restrict kernel pointers in /proc -----------------------------
kernel.kptr_restrict = 2

# ---- Kernel: Harden BPF -----------------------------------------------------
kernel.unprivileged_bpf_disabled = 1
net.core.bpf_jit_harden = 2

# ---- Kernel: Yama ptrace scope ----------------------------------------------
kernel.yama.ptrace_scope = 1

# ---- File system hardening --------------------------------------------------
fs.protected_hardlinks = 1
fs.protected_symlinks = 1
EOF

log_apply "Applying sysctl settings..."
sysctl --system &>/dev/null && log_pass "All sysctl parameters applied" || log_warn "Some sysctl parameters may not have applied"

# ---- Verify critical params -------------------------------------------------
CRITICAL_PARAMS=("net.ipv4.ip_forward" "kernel.randomize_va_space" "fs.suid_dumpable")
for param in "${CRITICAL_PARAMS[@]}"; do
    val=$(sysctl -n "$param" 2>/dev/null)
    log_pass "Verified $param = $val"
done

# ---- Disable IPv6 in GRUB (permanent) ---------------------------------------
GRUB_DEFAULT="/etc/default/grub"
backup_file "$GRUB_DEFAULT"

if ! grep -q "ipv6.disable=1" "$GRUB_DEFAULT"; then
    sed -i 's/GRUB_CMDLINE_LINUX="\(.*\)"/GRUB_CMDLINE_LINUX="\1 ipv6.disable=1"/' "$GRUB_DEFAULT"
    update-grub &>/dev/null && log_pass "GRUB updated: IPv6 disabled at boot" || log_warn "GRUB update failed"
fi

# ---- Disable unnecessary kernel modules -------------------------------------
MODPROBE_CONF="/etc/modprobe.d/cis-blacklist.conf"
backup_file "$MODPROBE_CONF"

cat > "$MODPROBE_CONF" << 'EOF'
# CIS Benchmark: Disable unused/dangerous filesystem and network modules
install cramfs /bin/true
install freevxfs /bin/true
install jffs2 /bin/true
install hfs /bin/true
install hfsplus /bin/true
install squashfs /bin/true
install udf /bin/true
install dccp /bin/true
install sctp /bin/true
install rds /bin/true
install tipc /bin/true
EOF
log_pass "Kernel module blacklist applied"

# ---- Disable core dumps via limits ------------------------------------------
LIMITS_CONF="/etc/security/limits.d/cis-coredump.conf"
echo "* hard core 0" > "$LIMITS_CONF"
log_pass "Core dumps disabled via /etc/security/limits.d"

# ---- systemd coredump -------------------------------------------------------
COREDUMP_CONF="/etc/systemd/coredump.conf"
backup_file "$COREDUMP_CONF"
set_config "Storage" "none" "$COREDUMP_CONF" "="
set_config "ProcessSizeMax" "0" "$COREDUMP_CONF" "="
log_pass "systemd coredump storage disabled"

echo -e "\n${GREEN}[KERNEL HARDENING COMPLETE]${NC}"
